import { MakeLogicType, afterMount, connect, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { projectLogic } from 'scenes/projectLogic'

import { sandboxCustomImagesList } from 'products/tasks/frontend/generated/api'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface signalsVisibleCustomImagesLogicValues {
    currentProjectId: number | null // projectLogic
    visibleImageCount: number | null
    visibleImageCountLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface signalsVisibleCustomImagesLogicActions {
    loadVisibleImageCount: () => any
    loadVisibleImageCountFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadVisibleImageCountSuccess: (
        visibleImageCount: number | null,
        payload?: any
    ) => {
        visibleImageCount: number | null
        payload?: any
    }
}

export type signalsVisibleCustomImagesLogicType = MakeLogicType<
    signalsVisibleCustomImagesLogicValues,
    signalsVisibleCustomImagesLogicActions
>

export const signalsVisibleCustomImagesLogic = kea<signalsVisibleCustomImagesLogicType>([
    path(['products', 'signals', 'inbox', 'logics', 'signalsVisibleCustomImagesLogic']),
    connect(() => ({ values: [projectLogic, ['currentProjectId']] })),
    loaders(({ values }) => ({
        visibleImageCount: [
            null as number | null,
            {
                loadVisibleImageCount: async (): Promise<number | null> => {
                    if (values.currentProjectId == null) {
                        return null
                    }
                    const page = await sandboxCustomImagesList(String(values.currentProjectId), { limit: 1 })
                    return page.count
                },
            },
        ],
    })),
    afterMount(({ actions }) => actions.loadVisibleImageCount()),
])
